mapper.select:
select 
from (
    select 
    from APP_PAY_SIGN_REQUEST
    where NVL(NOTIFY_RETRY_COUNT, 0) < #{maxRetry,jdbcType=INTEGER}
      and OPERATION_TYPE = 'RECEIVE_SIGN_RESULT'
      and (
            NOTIFY_STATUS = 'FAILED'
         or (NOTIFY_STATUS = 'PENDING'
             and NVL(NOTIFY_TIME, CREATE_TMS)
                 < SYSTIMESTAMP - NUMTODSINTERVAL(#{staleMinutes,jdbcType=INTEGER}, 'MINUTE'))
      )
    order by CREATE_TMS
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

mapper.update:
update APP_PAY_SIGN_REQUEST
set NOTIFY_STATUS = #{notifyStatus,jdbcType=VARCHAR},
    NOTIFY_TIME = #{notifyTime,jdbcType=TIMESTAMP},
    NOTIFY_RESULT = #{notifyResult,jdbcType=VARCHAR}

        , NOTIFY_RETRY_COUNT = #{notifyRetryCount,jdbcType=INTEGER}

where ID = #{id,jdbcType=BIGINT}
